  "hyeyeonPrologue": "얼음\n\n닿지 않았으면 싶었다.\n\n손끝 하나, 어쩌다 스친 옷깃까지도. 오늘은 그런 것에 기대어 마음을 바꾸고 싶지 않았다. 카페까지 오는 동안 나는 자꾸 보도블록의 바깥쪽으로 걸었다. 나란히 걷기에 충분히 넓은 길에서 혼자 어깨를 좁혔다.\n\n여름 끝물이었다. 덥지도, 끈적거리지도 않았다. 문이 열릴 때마다 제법 선선한 바람이 들어왔다. 그런데도 나는 자꾸 목이 말랐다.\n\n맞은편에 너를 앉혀놓고 삼십 분째 얼음만 먹었다. 물은 진작 바닥났고, 컵 안에는 작고 투명한 조각 몇 개가 남아 있었다. 하나를 입에 넣고 혀 밑으로 밀었다. 차가운 것이 닿아 있는 동안에는 말을 하지 않아도 됐다.\n\n오늘 만나자고 한 건 나였다.\n\n잠깐 얼굴 보자고 보낸 메시지가 이상하게 가벼워 보여서, 전송하고 나서도 한참 들여다봤다. 그렇다고 뒤에 무슨 말을 더 붙일 수는 없었다. 중요한 할 말이 있다는 문장은 너무 잔인했고, 보고 싶다는 문장은 아주 틀린 말이 아니라서 쓸 수 없었다.\n\n“……할 말 없냐고.”\n\n나는 컵을 내려다보며 중얼거렸다. 여기까지 와서도 입을 열지 못하는 내가 우스웠다. 준비한 말은 많았다. 씻으면서도, 옷을 입으면서도, 신호를 기다리면서도 몇 번씩 순서를 바꿔가며 외웠다.\n\n그런데 얼굴을 보자 전부 남의 말 같았다.\n\n“내가 보자고 해놓고, 너무 오래 앉혀뒀지.”\n\n무표정하게 말하려고 했다. 미안한 기색을 보이면 무슨 일이 있었느냐는 질문부터 받게 될 것 같았다. 그런 질문에는 제대로 대답할 자신이 없었다.\n\n무슨 일이 있었던 건 아니었다.\n\n그게 문제였다. 딱 잘라 꺼낼 만한 일이 없었다. 어느 날부터 연락을 기다리다가 잠드는 일이 줄었고, 서운한 게 생겨도 말하기 전에 귀찮아졌다. 설명하면 이해해줄까, 하던 생각이 설명해서 뭐 하나, 하는 생각으로 바뀌었다. 그러면서도 좋은 걸 보면 여전히 사진을 찍었다. 보내기 직전까지는 늘 네 생각을 했다.\n\n내 휴대폰에는 그렇게 찍고 보내지 않은 사진이 쌓여 있었다.\n\n“너한테 돌려줄 거 있어.”\n\n가방에서 열쇠를 꺼냈다. 테이블에 바로 놓지는 못하고 손바닥 안에 쥐었다. 작은 금속이 금방 미지근해졌다. 이걸 처음 받았을 때는 잃어버릴까 봐 지퍼가 달린 주머니에 따로 넣어 다녔다. 이제는 눈을 감고도 가방 안에서 찾아낼 수 있었다.\n\n“칫솔이랑…… 옷 몇 개는 버려도 돼. 가지러 가기에는 좀 그래서.”\n\n말하고 나서야 너무 멀리 와버렸다는 생각이 들었다.\n\n아직 헤어지자는 말도 못 했는데 버릴 물건부터 정하고 있었다. 나는 엄지로 열쇠의 홈을 문질렀다. 손바닥에 자국이 났다.\n\n컵을 다시 들었다. 얼음 하나가 입술에 걸렸다가 떨어지며 유리 벽을 쳤다. 생각보다 큰 소리가 났다. 옆자리 사람이 잠깐 돌아봤고, 나는 아무 일도 없다는 듯 컵을 내려놓았다.\n\n“우리 그만하자.”\n\n막상 뱉고 나니 평범한 목소리였다.\n\n이런 말을 하면 적어도 주변의 소음쯤은 멀어질 줄 알았다. 그런데 커피 내리는 소리도, 의자 끄는 소리도 그대로 들렸다. 직원은 다른 테이블에 케이크를 가져다줬다. 나는 그 접시에 포크가 두 개 놓여 있는 걸 끝까지 보고 있었다.\n\n고개를 돌리면 너를 봐야 했다.\n\n“화나서 하는 말 아니야. 네가 뭐 잘못해서 벌주려고 하는 것도 아니고.”\n\n거기서 말을 멈췄다. 이 문장까지는 어젯밤에 연습했다. 그다음에는 이제 좋아하지 않는다고 말할 생각이었다. 서로 시간 낭비하지 말자고, 더 늦기 전에 끝내는 게 맞는 것 같다고.\n\n하지만 눈앞에 앉은 사람에게 시간 낭비라는 말을 할 수는 없었다. 아프다고 하면 약을 사 들고 찾아가던 밤이나, 별것도 아닌 이야기를 하다가 함께 놓친 막차까지 그런 식으로 부르고 싶지는 않았다.\n\n“나 요즘 너 만나고 집에 가면, 우리가 무슨 얘기를 했는지 잘 생각이 안 나.”\n\n손 안에서 열쇠를 돌렸다.\n\n“내가 무슨 말을 참았는지만 생각나.”\n\n울 생각은 없었다. 오기 전에 거울 앞에서 눈 밑까지 꼼꼼히 확인했다. 잠을 못 잔 얼굴로 나오면 밤새 고민했다는 걸 들킬 것 같아서, 평소보다 오래 준비했다. 결국 이렇게 앉아서 입술 안쪽이나 깨물고 있을 거면서.\n\n“너도 그랬는지는 모르겠어. 나는…… 그랬어.”\n\n마침내 열쇠를 테이블에 놓았다. 손을 떼자 끝부분이 조금 젖어 있었다.\n\n한 번만 더 잘해보자는 말을 들으면 어떡하지. 알겠다는 말을 들으면 또 어떡하지. 어느 쪽도 감당할 준비가 안 됐다는 걸, 열쇠를 내려놓고 나서야 인정했다.\n\n나는 빈 컵을 쥐었다. 더는 입에 넣을 얼음이 없었다. 바닥에 고인 물은 한 모금도 되지 않았는데, 그것마저 마시고 싶은 걸 참았다.\n\n처음으로 네 얼굴을 제대로 봤다.\n\n“……왜 아무 말도 못 하게 하는지 알아?”\n\n목소리가 조금 갈라졌다. 나는 고개를 숙였다가 다시 들었다.\n\n“네 얘기까지 듣고 나면, 또 없던 일로 하고 싶어질까 봐.”\n\n컵에서 손을 뗐다. 테이블 아래로 감추려던 손이 어중간하게 가장자리에 남았다.\n\n“그래도 들어야겠지.”\n\n한참 뒤에야 다음 말을 붙였다.\n\n“너는…… 나랑 아직 만나고 싶어?”\n",
